fields.InputDefinition:
{
  "goal": "Open the 'People' entity grid — type 'People' in the LEFT sidebar 'Search record types...' box and click the EXACT 'People' match (not 'Person Job Functions'/'Member Profiles'/'Memberships'); if that is giving you trouble, navigate directly to http://localhost:4200/app/data-explorer/Data?entity=MJ_BizApps_Common:%20People. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away. Type 'Rodriguez' in the grid's filter box ('Filter records...'), click the row for Elena Rodriguez, then click 'Open Full Record' to view it in read mode. Find her Email field (elena.rodriguez.000101@lakemail.example). It should render as a styled clickable link with an envelope icon after the address (tooltip 'Send email'), not as plain text. Success is the Email field rendering as a styled link with the envelope icon.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 35,
  "judgeValidationCriteria": [
    "Elena Rodriguez's populated Email field renders as a clickable link with an envelope icon after the address",
    "The email address is styled as a hyperlink, visibly different from the plain-text values of non-link fields such as First Name",
    "No error messages, blank screens, or crash pages"
  ]
}
